    public void  predecessor(int n, ArrayList l) {
        Node node = search(n);
        if (node == null) return;

        if (node.left != null) {
            l.add(node.value);
            max(node.left, l); 
        } else {

            Node aux = node;
            while (aux.parent != null && aux.parent.value > n) {
                l.add(aux.value);
                aux = aux.parent;
            }

            l.add(aux.value);
            if (aux.parent != null)
                l.add(aux.parent.value);

        }
    }


