	int value;
	Node left, right;

	Node(int value) {
		this.value = value;
		this.left = null;
		this.right = null;
	}

	public void preOrder(ArrayList list) {
        list.add(this.value);
		if (this.left != null)
			this.left.preOrder(list);
		if (this.right != null)
			this.right.preOrder(list);
	}

	public void inOrder(ArrayList list) {
		if (this.left != null)
			this.left.inOrder(list);

        list.add(this.value);

		if (this.right != null)
