    static void heapify(int[] nums, int i) {

        int left = left(i);
        int right = right(i);
        int max = max(i, left, right, nums);


        if (max != i) {
            int tmp = nums[i];
            nums[i] = nums[max];
            nums[max] = tmp;
            heapify(nums, max);
        }

    }

    static int max(int i, int left, int right, int[] nums) {
        if (isValid(left, nums) && isValid(right, nums)) {

