		System.out.println(String.join(", ", livros));
		int indiceIt = indice;
		while (indiceIt > 0 && indice < livros.length) {
			if (livros[indiceIt].compareTo(livros[indiceIt - 1]) < 0)
				swap(livros, indiceIt, --indiceIt);
