        if (i >= v.length)
            return;
        else {
            int j = i;
            while (j > 0 && v[j] < v[j-1]) {
                swap(v,j, j-1);
                j--;
            }

            System.out.println(Arrays.toString(v));
            recInsertion(v, i+1);
        }
    }

    public static void swap(int[] v, int i , int j) {
        int aux = v[i];
        v[i] = v[j];
        v[j] = aux;
    }

}

